namespace SingleResponsibility
    {
        // MAL: mezcla lógica de juego, entrada de teclado y sonido en una sola clase.
        public class Character
        {
            public void Move(Vector2 direction) { /* lógica de movimiento */ }
            public void ReadKeyboardInput() { /* lee el input del teclado */ }
            public void PlayFootstepSound() { /* reproduce el sonido de paso */ }
        }

        // BIEN: cada responsabilidad, su propia clase.
        // CharacterMovement es núcleo (lógica pura); CharacterInput y CharacterAudio
        // son adaptadores (tocan el motor/el hardware).
        public class CharacterMovement
        {
            public void Move(Vector2 direction) { /* lógica pura, sin saber de input ni audio */ }
        }

        public class CharacterInput
        {
            public Vector2 ReadDirection() => Vector2.Zero; // adaptador: lee del teclado/mando
        }

        public class CharacterAudio
        {
            public void PlayFootstep() { /* adaptador: reproduce el sonido */ }
        }
    }

namespace OpenClosed
    {
        // MAL: agregar un enemigo nuevo obliga a volver a abrir este método.
        public class DamageCalculatorBad
        {
            public int CalculateDamage(string enemyType)
            {
                if (enemyType == "Goblin") return 10;
                else if (enemyType == "Dragon") return 50;
                // cada enemigo nuevo = tocar este if otra vez
                return 0;
            }
        }

        // BIEN: cada enemigo sabe su propio daño. Agregar uno nuevo no toca nada existente.
        public interface IEnemy { int Damage { get; } }
        public class Goblin : IEnemy { public int Damage => 10; }
        public class Dragon : IEnemy { public int Damage => 50; }
        public class Imp : IEnemy { public int Damage => 15; } // nuevo, sin tocar las otras clases
    }

namespace LiskovSubstitution
    {
        public class Player { }

        public class Enemy
        {
            public virtual void Chase(Player player) { /* se mueve hacia el jugador */ }
        }

        public class FixedTurret : Enemy
        {
            public override void Chase(Player player)
            {
                throw new NotSupportedException("Las torretas fijas no persiguen");
                // Cualquier código que reciba un Enemy y llame Chase() se rompe
                // si ese Enemy resulta ser un FixedTurret. Eso es violar Liskov.
            }
        }
    }

