namespace DependencyLevel1_DirectReference
    {
        public class GameState { }

        public class DiskSaveSystem
        {
            public void Write(GameState state) { /* ... */ }
        }

        // NIVEL 1: referencia directa. GameManager crea su propia dependencia, a mano.
        public class GameManager
        {
            private DiskSaveSystem saveSystem = new DiskSaveSystem();

            public void SaveGame(GameState state) => saveSystem.Write(state);
            // Problema: GameManager queda pegado para siempre a DiskSaveSystem.
            // No se puede guardar en la nube, ni testear sin tocar el disco real.
        }
    }

    namespace DependencyLevel2_Singleton
    {
        public class GameState { }

        // NIVEL 2: Singleton. Un único punto de acceso global.
        public class DiskSaveSystem
        {
            public static DiskSaveSystem Instance { get; } = new DiskSaveSystem();
            private DiskSaveSystem() { }
            public void Write(GameState state) { /* ... */ }
        }

        public class GameManager
        {
            public void SaveGame(GameState state) => DiskSaveSystem.Instance.Write(state);
            // Mejora: ya no se crea una instancia nueva en cada lugar que la necesita.
            // Lo que sigue mal: GameManager sigue sabiendo el nombre concreto
            // DiskSaveSystem — sigue "soldado", solo que ahora accede distinto.
        }
    }

    namespace DependencyLevel3_ServiceLocator
    {
        public class GameState { }
        public interface ISaveSystem { void Write(GameState state); }

        // NIVEL 3: Service Locator. Se pide una INTERFAZ, no una clase concreta.
        public static class Services
        {
            private static Dictionary<Type, object> registered = new();
            public static void Register<T>(T instance) => registered[typeof(T)] = instance;
            public static T Get<T>() => (T)registered[typeof(T)];
        }

        public class GameManager
        {
            public void SaveGame(GameState state)
            {
                var saveSystem = Services.Get<ISaveSystem>();
                saveSystem.Write(state);
                // Mejora: clavija, no cable soldado — cualquier ISaveSystem sirve.
                // Lo que sigue mal: la dependencia está escondida adentro del método,
                // no se ve mirando la clase. Y si nadie la registró antes, explota en runtime.
            }
        }
    }

    namespace DependencyLevel4_DependencyInjection
    {
        public class GameState { }
        public interface ISaveSystem { void Write(GameState state); }

        // NIVEL 4: Inyección de dependencias. La dependencia entra por el constructor,
        // visible, obligatoria, chequeada en tiempo de compilación.
        public class GameManager
        {
            private readonly ISaveSystem saveSystem;

            public GameManager(ISaveSystem saveSystem) // <- acá, visible
            {
                this.saveSystem = saveSystem;
            }

            public void SaveGame(GameState state) => saveSystem.Write(state);
        }
    }

