    namespace VehicleWithComposition
    {
        // CON COMPOSICIÓN: las capacidades se combinan, no se heredan.
        public interface IMovementCapability { void Move(); }

        public class LandMovement : IMovementCapability
        {
            public void Move() { /* conducir */ }
        }

        public class WaterMovement : IMovementCapability
        {
            public void Move() { /* flotar */ }
        }

        public class Vehicle
        {
            private readonly List<IMovementCapability> capabilities = new();
            public void AddCapability(IMovementCapability capability) => capabilities.Add(capability);
        }

        public static class Demo
        {
            public static void BuildAmphibiousVehicle()
            {
                // El anfibio simplemente tiene DOS capacidades. Sin pelear con el árbol.
                var amphibiousVehicle = new Vehicle();
                amphibiousVehicle.AddCapability(new LandMovement());
                amphibiousVehicle.AddCapability(new WaterMovement());
            }
        }
    }

