    namespace CompositionBoxExample
    {
        public interface ICapability
        {
            void Activate(Box box); // qué pasa cuando esta capacidad se activa
        }

        public class Pushable : ICapability
        {
            public void Activate(Box box) => box.Position += Vector2.Right;
        }

        public class Flammable : ICapability
        {
            public void Activate(Box box) => box.IsOnFire = true;
        }

        public class SpawnsEnemies : ICapability
        {
            public void Activate(Box box) => box.SpawnEnemies(3);
        }

        public class Box
        {
            public Vector2 Position;
            public bool IsOnFire;
            private readonly List<ICapability> capabilities = new();

            public void AddCapability(ICapability capability) => capabilities.Add(capability);

            public void Break()
            {
                foreach (var capability in capabilities)
                    capability.Activate(this); // cada capacidad hace lo suyo
            }

            public void SpawnEnemies(int count) { /* ... */ }
        }
    }

