namespace CommandPatternExample
    {
        public interface ICommand
        {
            void Execute();
            void Undo();
        }

        public class MoveCommand : ICommand
        {
            private readonly Board board;
            private readonly Position from;
            private readonly Position to;
            private Piece capturedPiece; // se completa recién al ejecutar

            public MoveCommand(Board board, Position from, Position to)
            {
                this.board = board;
                this.from = from;
                this.to = to;
            }

            public void Execute()
            {
                capturedPiece = board.PieceAt(to);   // guardamos lo necesario para deshacer
                board.MovePiece(from, to);
            }

            public void Undo()
            {
                board.MovePiece(to, from);
                if (capturedPiece != null)
                    board.PlacePiece(capturedPiece, to); // devolvemos la pieza capturada
            }
        }

        // Test de ejemplo (referenciado en los apuntes del profesor).
        public class CommandTests
        {
            public void MoveCommand_ExecuteThenUndo_RestoresOriginalBoard()
            {
                var board = new Board();
                var from = new Position(1, 0);
                var to = new Position(2, 0);
                board.PlacePiece(new Piece("Pawn", "White"), from);

                var boardBefore = board.Clone();                // Arrange
                var command = new MoveCommand(board, from, to);

                command.Execute();                               // Act
                command.Undo();

                // Assert.AreEqual(boardBefore, board);          // Assert
            }
        }
    }
}

namespace CoreTestability
    {
        public class Position { }
        public class Piece
        {
            public List<Position> PossibleMoves(Board board, Position origin) => new();
        }
        public class Board
        {
            public Piece PieceAt(Position position) => null;
        }

        public class MoveValidator
        {
            // Testabilidad real: esta función es pura. Mismo tablero + mismo movimiento
            // = mismo resultado, siempre. No necesita ninguna infraestructura para testearse.
            public bool IsValidMove(Board board, Position origin, Position destination)
            {
                var piece = board.PieceAt(origin);
                if (piece == null) return false;
                return piece.PossibleMoves(board, origin).Contains(destination);
            }
        }
    }

namespace TestDoubles
    {
        public class Reservation
        {
            public int Id { get; }
            public Reservation(int id) => Id = id;
        }

        public interface IReservationRepository
        {
            Reservation FindById(int id);
            void Save(Reservation reservation);
        }

        // STUB: siempre devuelve el mismo dato fijo. No importa qué le pidan, responde igual.
        public class StubReservationRepository : IReservationRepository
        {
            public Reservation FindById(int id) => new Reservation(id);
            public void Save(Reservation reservation) { /* no hace nada */ }
        }

        public interface IEmailSender { void Send(string message); }

        // MOCK: guarda evidencia de cómo lo usaron, para poder verificarlo en el Assert.
        public class MockEmailSender : IEmailSender
        {
            public int TimesSendWasCalled { get; private set; }
            public string LastMessageSent { get; private set; }

            public void Send(string message)
            {
                TimesSendWasCalled++;
                LastMessageSent = message;
            }
        }
        // En el test: Assert.AreEqual(1, mockSender.TimesSendWasCalled);

        // FAKE: funciona de verdad, pero simplificado — una lista en memoria
        // en vez de una base de datos real.
        public class InMemoryReservationRepository : IReservationRepository
        {
            private readonly Dictionary<int, Reservation> storage = new();

            public Reservation FindById(int id) => storage[id];
            public void Save(Reservation reservation) => storage[reservation.Id] = reservation;
        }
    }

